import{_ as a,c as r,o as n,j as o,Y as s,t as i}from"./chunks/framework.D-NV0Bun.js";const u=JSON.parse('{"title":"termio | x-cmd man (man7) | System V terminal driver interface","titleTemplate":false,"description":"x-cmd man (man7 Manual Page) | termio - System V terminal driver interface","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"termio | x-cmd man (man7) | System V terminal driver interface"}],["meta",{"name":"og:description","content":"x-cmd man (man7 Manual Page) | termio - System V terminal driver interface"}]]},"headers":[],"params":{"isMan":true,"man":"termio","category":"man7","desc":"System V terminal driver interface"},"relativePath":"man7/termio.md","filePath":"man7/[man].md"}'),m={name:"man7/termio.md"},d={class:"visually-hidden"};function l(t,e,c,g,h,f){return n(),r("div",null,[o("h1",d,i(t.$params.man),1),e[0]||(e[0]=s('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>termio - System V terminal driver interface</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p><strong>termio</strong> is the name of the old System V terminal driver interface. This interface defined a <em>termio</em> structure used to store terminal settings, and a range of <strong>ioctl</strong>(2) operations to get and set terminal attributes.</p><p>The <strong>termio</strong> interface is now obsolete: POSIX.1-1990 standardized a modified version of this interface, under the name <strong>termios</strong>. The POSIX.1 data structure differs slightly from the System V version, and POSIX.1 defined a suite of functions to replace the various <strong>ioctl</strong>(2) operations that existed in System V. (This was done because <strong>ioctl</strong>(2) was unstandardized, and its variadic third argument does not allow argument type checking.)</p><p>If you&#39;re looking for a page called &quot;termio&quot;, then you can probably find most of the information that you seek in either <strong>termios</strong>(3) or <strong>ioctl_tty</strong>(2).</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>reset</strong>(1), <strong>setterm</strong>(1), <strong>stty</strong>(1), <strong>ioctl_tty</strong>(2), <strong>termios</strong>(3), <strong>tty</strong>(4)</p>',8))])}const S=a(m,[["render",l]]);export{u as __pageData,S as default};
